ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), price = VALUES(price), shipping_cost = VALUES(shipping_cost), image_path = VALUES(image_path);

-- Every imported card belongs to the "cards" category
SELECT p.id, c.id FROM products p JOIN categories c ON c.slug = 'cards' WHERE p.external_id LIKE 'tcgdex:%';

-- Card attributes, linked by codes through a temporary table
CREATE TEMPORARY TABLE card_attributes (external_id VARCHAR(64), property_code VARCHAR(50), value_code VARCHAR(50));
SELECT p.id, pv.id
  FROM card_attributes a
  JOIN products p         ON p.external_id = a.external_id
  JOIN properties pr      ON pr.code = a.property_code
  JOIN property_values pv ON pv.property_id = pr.id AND pv.code = a.value_code;
DROP TEMPORARY TABLE card_attributes;
